BEGIN READ ONLY; SET LOCAL statement_timeout='8s'; SET LOCAL lock_timeout='1s';
SELECT jsonb_build_object(
 'profile_update_role',has_column_privilege('authenticated','public.profiles','role','UPDATE'),
 'profile_triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'function',p.proname,'internal',t.tgisinternal,'enabled',t.tgenabled)),'[]') FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid='public.profiles'::regclass),
 'profile_constraints',(SELECT jsonb_agg(jsonb_build_object('name',conname,'type',contype,'definition_masked',regexp_replace(pg_get_constraintdef(oid),'''([^'']|'''')*''','''<literal>''','g'))) FROM pg_constraint WHERE conrelid='public.profiles'::regclass),
 'sensitive_column_access',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'anon_select',has_column_privilege('anon',c.oid,a.attnum,'SELECT'),'authenticated_select',has_column_privilege('authenticated',c.oid,a.attnum,'SELECT'),'authenticated_update',has_column_privilege('authenticated',c.oid,a.attnum,'UPDATE'))) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r' AND a.attnum>0 AND NOT a.attisdropped AND a.attname ~* '(secret|token|password|api_key)'),
 'role_membership',(SELECT jsonb_agg(jsonb_build_object('role',pg_get_userbyid(roleid),'member',pg_get_userbyid(member),'inherit',inherit_option,'set',set_option)) FROM pg_auth_members WHERE pg_get_userbyid(member) IN ('anon','authenticated','authenticator','service_role','postgres')),
 'extension_security',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'function',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'settings',p.proconfig,'acl',p.proacl::text)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('net','graphql_public') AND p.prokind='f'),
 'net_grants',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'acl',c.relacl::text,'rls',c.relrowsecurity)) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='net' AND c.relkind IN ('r','S'))
) AS metadata; ROLLBACK;

BEGIN READ ONLY; SET LOCAL statement_timeout='8s'; SET LOCAL lock_timeout='1s';
WITH fs AS (SELECT p.oid,p.proname,p.prosrc, n.nspname,pg_get_function_identity_arguments(p.oid) args FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private') AND p.prokind='f'),
rs AS (SELECT c.relname,n.nspname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','private') AND c.relkind IN ('r','p','v','m','S'))
SELECT jsonb_agg(jsonb_build_object('schema',f.nspname,'name',f.proname,'arguments',f.args,
 'function_name_mentions',(SELECT coalesce(jsonb_agg(DISTINCT x.nspname||'.'||x.proname),'[]') FROM fs x WHERE x.oid<>f.oid AND f.prosrc ~ ('\m'||x.proname||'\M')),
 'relation_name_mentions',(SELECT coalesce(jsonb_agg(r.nspname||'.'||r.relname),'[]') FROM rs r WHERE f.prosrc ~ ('\m'||r.relname||'\M'))
)) AS metadata FROM fs f; ROLLBACK;

BEGIN READ ONLY; SET LOCAL statement_timeout='8s'; SET LOCAL lock_timeout='1s';
SELECT jsonb_build_object('triggers',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'function_schema',fn.nspname,'function',p.proname,'enabled',t.tgenabled)) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace fn ON fn.oid=p.pronamespace WHERE NOT t.tgisinternal AND fn.nspname IN ('public','private')),
 'dependency_constraints',(SELECT jsonb_agg(jsonb_build_object('table_schema',tn.nspname,'table',c.relname,'constraint',con.conname,'function_schema',fn.nspname,'function',p.proname)) FROM pg_depend d JOIN pg_constraint con ON d.classid='pg_constraint'::regclass AND d.objid=con.oid JOIN pg_proc p ON d.refclassid='pg_proc'::regclass AND d.refobjid=p.oid JOIN pg_namespace fn ON fn.oid=p.pronamespace JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace tn ON tn.oid=c.relnamespace WHERE fn.nspname IN ('public','private')),
 'db_temp',(SELECT jsonb_agg(jsonb_build_object('role',r,'temp',has_database_privilege(r,current_database(),'TEMP'))) FROM unnest(ARRAY['anon','authenticated','service_role']) r)
) AS metadata; ROLLBACK;
